// File: ratelimit/token_bucket.go
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock abstracts time so tests can inject a fake.
type Clock interface {
	Now() time.Time
}

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket starts full and refills at rate tokens per second,
// capped at burst tokens.
type Limiter struct {
	mu     sync.Mutex
	clock  Clock
	rate   float64 // tokens added per second
	burst  float64 // maximum tokens
	tokens float64 // current tokens
	last   time.Time
}

// NewLimiter validates its arguments and returns a fully primed limiter.
func NewLimiter(rate, burst float64, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if math.IsNaN(rate) || math.IsInf(rate, 0) || rate <= 0 {
		return nil, errors.New("ratelimit: rate must be a positive finite number")
	}
	if math.IsNaN(burst) || math.IsInf(burst, 0) || burst <= 0 {
		return nil, errors.New("ratelimit: burst must be a positive finite number")
	}
	now := clock.Now()
	return &Limiter{clock: clock, rate: rate, burst: burst, tokens: burst, last: now}, nil
}

// Allow reports whether one token may be consumed.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens may be consumed.
// n <= 0 never consumes tokens; n < 0 is rejected, n == 0 succeeds.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	if n == 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	l.tokens += now.Sub(l.last).Seconds() * l.rate
	if l.tokens > l.burst {
		l.tokens = l.burst
	}
	l.last = now
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}
